  gap: 8px;
  padding: 8px 10px;
}

.ocean-surface--extension .ocean-brand {
  min-width: 0;
}


.ocean-surface--extension .ocean-header__right {
  flex: 1 1 auto;
  min-width: 0;
  flex-wrap: nowrap;
  gap: 4px;
  justify-content: flex-end;
}

.ocean-surface--extension .ocean-runtime {
  flex: 0 1 auto;
  min-width: 0;
  gap: 6px;
  padding-left: 0;
  box-shadow: none;
}

.ocean-surface--extension .ocean-runtime .ocean-tokens {
  display: none;
}

.ocean-surface--extension .ocean-browser-control {
  width: var(--ctl-h-sm);
  padding: 0;
  justify-content: center;
}

.ocean-surface--extension .ocean-browser-control__label {
  display: none;
}

.ocean-surface--extension .ocean-runtime .ocean-status {
  flex: 0 1 auto;
  max-width: 96px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
/* Header controls and per-turn selectors use compact control height. */
  .ocean-surface--extension .ocean-sessions-trigger,
  .ocean-surface--extension .ocean-thinking,
  .ocean-surface--extension .ocean-model-override {
    min-height: var(--ctl-h-sm);
    height: var(--ctl-h-sm);
  }

.ocean-surface--extension .ocean-thinking,
.ocean-surface--extension .ocean-model-override {
  max-width: 46vw;
}

/* Transcript and canvas regions keep readable gutters in a narrow column. */
.ocean-surface--extension .transcript {
  padding: 12px 14px;
  gap: 12px;
}

.ocean-surface--extension .block--text {
  max-width: 100%;
  overflow-x: auto;
}

.ocean-surface--extension .ocean-canvas {
  margin: 8px 10px 0;
}

.ocean-surface--extension .ocean-canvas__head,
.ocean-surface--extension .ocean-canvas__tabs {
  padding-right: 10px;
  padding-left: 10px;
}

/* Composer compresses without changing the base control recipes. */
.ocean-surface--extension .ocean-composer {
  padding: 8px 10px 10px;
  gap: 8px;
}

.ocean-surface--extension .voice-wrap {
  gap: 6px;
}

.ocean-surface--extension .voice-orb {
  width: 32px;
  height: 32px;
  font-size: 16px;
}

.ocean-surface--extension .voice-hint {
  display: none;
}

