  .ocean-surface .ocean-composer__send {
    min-height: var(--ctl-h-sm);
    height: var(--ctl-h-sm);
  }

  /* Rich content: clip instead of widening viewport ------------------ */
  .ocean-surface pre,
  .ocean-surface img,
  .ocean-surface table {
    max-width: 100%;
    overflow-x: auto;
  }
}

/* Wide rich content clips in the side panel instead of widening it. */
.ocean-surface--extension pre,
.ocean-surface--extension img,
.ocean-surface--extension table {
  max-width: 100%;
  overflow-x: auto;
}

/* ── Narrow component reflow (≤480px) — stack kanban, cardify tables,
   full-width charts, single-col stats/dashboards. True reflow, not
   overflow-x band-aids. ─────────────────────────────────────────────── */
@media (max-width: 480px) {
  /* Container: prevent turn body from growing past viewport --------- */
  .ocean-surface .turn--assistant .turn__body {
    min-width: 0;
    overflow: hidden;
  }

  /* All component wrappers: fill the turn body, don't push offscreen */
  .ocean-surface .component-kanban,
  .ocean-surface .component-form,
  .ocean-surface .component-table,
  .ocean-surface .component-progress,
  .ocean-surface .component-markdown,
  .ocean-surface .component-dashboard,
  .ocean-surface .component-chart,
  .ocean-surface .component-timeline,
  .ocean-surface .component-stats,
  .ocean-surface .component-filetree,
  .ocean-surface .component-diff,
  .ocean-surface .component-code,
  .ocean-surface .component-callout,
  .ocean-surface .component-gallery,
  .ocean-surface .component-confirm,
  .ocean-surface .block--map,
  .ocean-surface .block--video,
  .ocean-surface .block--component-unknown {
    width: 100%;
    max-width: 100%;
    min-width: 0;
    box-sizing: border-box;
  }

  /* Kanban: stack columns vertically -------------------------------- */
  .ocean-surface .kanban-columns {
    flex-direction: column;
    gap: 12px;
    max-height: none;
    overflow-x: visible;
  }
  .ocean-surface .kanban-column {
    min-width: 0;
    max-width: none;
    flex: 1 1 auto;
    width: 100%;
  }

  /* Table: cardify rows — hide thead, display tr/td as blocks ----- */
  .ocean-surface .component-table {
    overflow-x: visible;
  }
  .ocean-surface .data-table {
    display: block;
    min-width: 0;
    width: 100%;
  }
  .ocean-surface .data-table thead {
    display: none;
  }
  .ocean-surface .data-table tbody {
    display: block;
  }
  .ocean-surface .data-table__row {
    display: block;
    margin-bottom: 6px;
    background: var(--bg-elevated);
    border: 1px solid var(--border-subtle);
    border-radius: var(--radius);
  }
  .ocean-surface .data-table td {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px;
    padding: 6px 12px;
    border-bottom: none;
    text-align: right;
  }
  .ocean-surface .data-table td:not(:last-child) {
    border-bottom: 1px solid var(--border-subtle);
  }
  .ocean-surface .data-table td::before {
    content: attr(data-label);
    flex: 0 0 auto;
    color: var(--fg-3);
    font-size: 11px;
    font-weight: 600;
    white-space: nowrap;
  }
  .ocean-surface .data-table__footer {
    margin-top: 4px;
    border-top: 1px solid var(--border-subtle);
  }

  /* Chart: label wraps to full row, track follows ------------------- */
  .ocean-surface .chart-row {
    flex-wrap: wrap;
    gap: 4px 8px;
    min-height: auto;
    padding: 4px 6px;
  }
  .ocean-surface .chart-row__label {
    flex: 1 1 100%;
    max-width: none;
    white-space: normal;
    overflow: visible;
    text-overflow: clip;
  }
  .ocean-surface .chart-row__track {
    flex: 1 1 auto;
  }

  /* Stats: single column -------------------------------------------- */
  .ocean-surface .component-stats {
    grid-template-columns: 1fr;
  }
  .ocean-surface .stat-card {
    min-width: 0;
  }

  /* Form: full width ------------------------------------------------ */
  .ocean-surface .component-form form {
    width: 100%;
  }

  /* Progress: full width -------------------------------------------- */
  .ocean-surface .component-progress {
    width: 100%;
  }

  /* Gallery: tighter grid ------------------------------------------- */
  .ocean-surface .component-gallery {
    grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
  }

  /* Dashboard: single column (override inline grid-template-columns) */
  .ocean-surface .component-dashboard {
    grid-template-columns: 1fr !important;
    overflow-x: visible;
  }
  .ocean-surface .dashboard-cell {
    min-width: 0;
  }

  /* Confirm: wrap action buttons ------------------------------------ */
  .ocean-surface .confirm__actions {
    flex-wrap: wrap;
  }

}

