text:
     1	/* ─── Composer dock + voice input ───────────────────────────────────────────
     2	   Visual contract: product-register controls from docs/OCEAN_WEB_SURFACE_DESIGN.md.
     3	   Rust owns behavior and class names; this file only skins the emitted surface.
     4	   ───────────────────────────────────────────────────────────────────────── */
     5	
     6	/* One compact dock card. The writing row owns the full width; the lower
     7	   toolbar keeps voice, turn controls, and the single action slot aligned.
     8	   The FORM is the only framed surface and owns the focus ring. */
     9	.ocean-composer {
    10	  display: grid;
    11	  grid-template-columns: auto minmax(0, 1fr) auto;
    12	  grid-template-areas:
    13	    "input input input"
    14	    "orb controls action";
    15	  align-items: center;
    16	  column-gap: 8px;
    17	  row-gap: 4px;
    18	  margin: 8px 18px 12px;
    19	  padding: 8px 12px;
    20	  border-radius: var(--radius-lg);
    21	  background: var(--bg-elevated);
    22	  box-shadow: var(--elev-2);
    23	  transition: box-shadow var(--dur) var(--ease-tide);
    24	}
    25	.ocean-composer:focus-within {
    26	  box-shadow: var(--elev-2), var(--focus-ring);
    27	}
    28	
    29	/* ── voice orb ─────────────────────────────────────────────────────────── */
    30	
    31	.voice-wrap {
    32	  position: relative;
    33	  grid-area: orb;
    34	  display: flex;
    35	  flex: 0 0 auto;
    36	  flex-direction: row;
    37	  gap: 2px;
    38	  align-items: center;
    39	  align-self: center;
    40	}
    41	
    42	.voice-orb {
    43	  appearance: none;
    44	  display: grid;
    45	  width: var(--ctl-h);
    46	  height: var(--ctl-h);
    47	  place-items: center;
    48	  border: 1px solid var(--border);
    49	  border-radius: var(--radius-pill);
    50	  background: var(--bg-elevated);
    51	  color: var(--fg-3);
    52	  font: inherit;
    53	  cursor: pointer;
    54	  -webkit-user-select: none;
    55	  user-select: none;
    56	  touch-action: none;
    57	  transition:
    58	    transform var(--dur-fast) var(--ease),
    59	    border-color var(--dur-fast) var(--ease),
    60	    background var(--dur-fast) var(--ease),
    61	    color var(--dur-fast) var(--ease),
    62	    box-shadow var(--dur-fast) var(--ease),
    63	    opacity var(--dur-fast) var(--ease);
    64	}
    65	
    66	.voice-orb:hover {
    67	  border-color: var(--border-strong);
    68	  background: var(--bg-hover);
    69	  color: var(--fg);
    70	}
    71	
    72	.voice-orb:focus-visible {
    73	  outline: none;
    74	  box-shadow: var(--focus-ring);
    75	}
    76	
    77	.voice-orb:active {
    78	  transform: scale(0.985);
    79	}
    80	
    81	.voice-orb.is-disabled,
    82	.voice-orb:disabled {
    83	  opacity: 0.45;
    84	  cursor: not-allowed;
    85	  pointer-events: none;
    86	}
    87	
    88	.voice-orb__glyph {
    89	  display: inline-flex;
    90	  pointer-events: none;
    91	  color: currentColor;
    92	}
    93	
    94	.voice-orb__glyph .icon,
    95	.voice-orb__glyph svg {
    96	  width: 18px;
    97	  height: 18px;
    98	}
    99	
   100	.voice-orb.is-recording {
   101	  border-color: transparent;
   102	  background: var(--accent);
   103	  color: var(--fg-on-accent);
   104	  box-shadow: var(--glow-brand);
   105	  animation: voice-pulse 1.35s var(--ease) infinite;
   106	}
   107	
   108	.voice-orb.is-transcribing {
   109	  border-color: var(--warn);
   110	  background: var(--warn-soft);
   111	  color: var(--warn);
   112	  animation: voice-transcribe 1.4s var(--ease) infinite;
   113	}
   114	
   115	.voice-orb.is-live {
   116	  border-color: var(--accent);
   117	  background: var(--accent-soft);
   118	  color: var(--accent);
   119	  --voice-listen-pulse: var(--accent-soft);
   120	  animation: voice-listen 2.4s var(--ease) infinite;
   121	}
   122	
   123	.voice-orb.is-live.is-capturing {
   124	  border-color: transparent;
   125	  background: var(--accent);
   300	  line-height: 1.4;
   301	  letter-spacing: 0.06em;
   302	  text-transform: uppercase;
   303	  color: var(--fg-3);
   304	  user-select: none;
   305	}
   306	
   307	/* Spoken-replies toggle — a quiet row with a trailing state dot (::after);
   308	   is-on blooms the dot aqua to read as "replies on". */
   309	.voice-menu__toggle {
   310	  display: flex;
   311	  align-items: center;
   312	  justify-content: space-between;
   313	  gap: 8px;
   314	  width: 100%;
   315	  padding: 8px;
   316	  border: none;
   317	  border-radius: var(--radius-sm);
   318	  background: transparent;
   319	  color: var(--fg);
   320	  font-size: 12px;
   321	  line-height: 1.3;
   322	  text-align: left;
   323	  cursor: pointer;
   324	  transition: background var(--dur-fast) var(--ease);
   325	}
   326	
   327	.voice-menu__toggle:hover {
   328	  background: var(--bg-hover);
   329	}
   330	
   331	.voice-menu__toggle:focus-visible {
   332	  outline: none;
   333	  box-shadow: var(--focus-ring);
   334	}
   335	
   336	.voice-menu__toggle::after {
   337	  content: "";
   338	  flex: 0 0 auto;
   339	  width: 7px;
   340	  height: 7px;
   341	  border-radius: var(--radius-pill);
   342	  background: var(--border-strong);
   343	  transition:
   344	    background var(--dur-fast) var(--ease),
   345	    box-shadow var(--dur-fast) var(--ease);
   346	}
   347	
   348	.voice-menu__toggle.is-on::after {
   349	  background: var(--accent);
   350	  box-shadow: 0 0 6px var(--accent-soft);
   351	}
   352	
   353	/* Privacy footnote — small, muted, the last word on what leaves the device. */
   354	.voice-menu__note {
   355	  padding: 6px 8px 2px;
   356	  font-size: 10px;
   357	  line-height: 1.4;
   358	  color: var(--fg-3);
   359	}
   360	
   361	/* ── voice trigger + live chip ────────────────────────────────────────── */
   362	/* The trigger is a ghost chevron that opens the menu — quiet by default,
   363	   found on hover/focus, with a 0.35 floor so touch users always reach it.
   364	   The live chip shows only while hands-free is hot: a pulsing aqua dot. */
   365	
   366	.voice-trigger {
   367	  appearance: none;
   368	  flex: 0 0 auto;
   369	  display: inline-flex;
   370	  align-items: center;
   371	  justify-content: center;
   372	  width: 20px;
   373	  height: 20px;
   374	  padding: 0;
   375	  border: none;
   376	  background: transparent;
   377	  color: var(--fg-3);
   378	  font-size: 12px;
   379	  opacity: 0.35;
   380	  cursor: pointer;
   381	  transition:
   382	    opacity var(--dur-fast) var(--ease),
   383	    color var(--dur-fast) var(--ease);
   384	}
   385	
   386	.voice-trigger .icon,
   387	.voice-trigger svg {
   388	  width: 1em;
   389	  height: 1em;
   390	}
   391	
   392	.voice-wrap:hover .voice-trigger,
   393	.voice-wrap:focus-within .voice-trigger,
   394	.voice-wrap:has(.voice-menu) .voice-trigger {
   395	  opacity: 1;
   396	}
   397	
   398	.voice-trigger:hover {
   399	  color: var(--fg);
   400	  opacity: 1;
   401	}
   402	
   403	.voice-trigger:focus-visible {
   404	  outline: none;
   405	  opacity: 1;
   406	  box-shadow: var(--focus-ring);
   407	  border-radius: var(--radius-sm);
   408	}
   409	
   410	.voice-live-chip {
   411	  display: inline-flex;
   412	  align-items: center;
   413	  gap: 6px;
   414	  padding: 2px 8px;
   415	  border: 1px solid var(--border-subtle);
   416	  border-radius: var(--radius-pill);
   417	  background: var(--bg-raised);
   418	  color: var(--fg-2);
   419	  font-size: 10px;
   420	  line-height: 1;
   421	  cursor: pointer;
   422	  transition:
   423	    border-color var(--dur-fast) var(--ease),
   424	    color var(--dur-fast) var(--ease);
   425	}
   426	
   427	.voice-live-chip:hover {
   428	  border-color: var(--border-strong);
   429	  color: var(--fg);
   430	}
   431	
   432	.voice-live-chip:focus-visible {
   433	  outline: none;
   434	  box-shadow: var(--focus-ring);
   435	}
   436	
   437	/* Pulsing dot — the hot aqua behind --glow-live (ocean-7 / --accent-bright),
   438	   the same live family the call styles ring speaking tiles with. */
